def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_opp = 0
    weak_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) > 180 and opp.get('hp', 0) >= 6:
                strong_opp += 1
            if opp.get('budget', 0) < 90 or opp.get('hp', 0) <= 2:
                weak_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid'))

    if not alive:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    total_players = len(alive) + 1
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < total_players
    severe_scarcity = expected_units < max(1.5, total_players - 1)

    need_urgent = hp <= 3 or no_water_days >= 2
    need_high = hp <= 5 or no_water_days >= 1

    if need_urgent:
        bid = max(145.0, highest_prev + 3.0)
    elif severe_scarcity:
        bid = max(132.0, highest_prev + 2.0)
    elif scarcity:
        bid = max(118.0, avg_prev + 2.5)
    else:
        bid = 78.0

    if weak_opp >= 2 and not need_high:
        bid -= 10.0
    if strong_opp >= 3 and scarcity:
        bid += 6.0
    if float(supply) >= 23.0 and not need_high:
        bid -= 12.0
    if float(supply) <= 17.0:
        bid += 8.0
    if day >= 8:
        bid += 6.0

    reserve = 0.0
    if hp >= 7 and no_water_days == 0:
        reserve = 35.0
    elif hp >= 5:
        reserve = 20.0

    max_affordable = max(0.0, budget - reserve)
    if need_urgent:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if budget < 60.0:
        if need_urgent:
            bid = budget
        else:
            bid = min(bid, max(18.0, budget * 0.55))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if budget <= 0:
        return 0.0

    # Base bid: target enough to cover my requirement without going extreme.
    # With supply in [15,25], a mid bid should often secure water without bankrupting.
    base_bid = 0.55 * DAILY_SALARY  # 82.5

    # Extract yesterday bids to infer opponent aggressiveness.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure from yesterday: if someone was willing to pay very high, others likely also bid hard.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # My urgency: low hp or accumulating no_water_days increases bid.
    urgency = 0.0
    if hp <= 2:
        urgency += 0.40
    elif hp <= 4:
        urgency += 0.20

    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days >= 1:
        urgency += 0.10

    # Opponent aggressiveness adjustment.
    # Yesterday maxima ~158; if near that, increase slightly to avoid being outbid.
    aggression = 0.0
    if highest_prev_bid >= 140.0:
        aggression = 0.25
    elif highest_prev_bid >= 120.0:
        aggression = 0.15
    elif highest_prev_bid >= 100.0:
        aggression = 0.08

    # Also, if average was high, keep bids closer to the middle-upper range.
    if avg_prev_bid >= 120.0:
        aggression += 0.08

    target = base_bid * (1.0 + urgency + aggression)

    # Safety cap: never exceed what I can afford; also avoid extreme spending.
    # Cap around 0.9*DAILY_SALARY unless I am critically low.
    critical = (hp <= 1) or (no_water_days >= 3)
    max_reasonable = 0.95 * DAILY_SALARY if critical else 0.75 * DAILY_SALARY
    target = min(target, max_reasonable)

    # If supply is very tight (near MIN_SUPPLY), bid slightly more to secure water.
    if supply <= float(MIN_SUPPLY) + 0.5:
        target *= 1.10

    # Final affordability clamp.
    bid = min(float(budget), float(target))

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], 155.0))

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        target = min(150.0, avg_bid + 2.0)
        return float(min(my_status['budget'], target))

    return float(min(my_status['budget'], 85.0))
